yaml:
rules:
  - id: dubbo-npe-c1-r1
    languages:
      - java
    severity: ERROR
    message: >-
      A possibly-null value is used without a null guard, which can throw a
      NullPointerException. This covers (1) the URL component field
      'urlAddress', left null by the no-arg constructor chain (URL() /
      ServiceConfigURL() / URLBuilder()); (2) the result of the nullable
      getServiceInfo() / getValidServiceInfo() lookups, which return null when
      no matching ServiceInfo exists; (3) URL username/password credentials
      populated only from the inline 'user:password@' userinfo segment, which
      stay null when that segment is absent or the URL body was truncated at
      '#'; and (4) a possibly-null invocation attachment (e.g. the service
      path) that is fed into the service-key/cache-key builder without being
      validated, so a null ends up as a ConcurrentHashMap key and raises a
      misleading NullPointerException. In every case the fix adds a null/empty
      check (or a fallback) before the value is used, e.g. if (x == null) return
      ...; if (x != null) { ... }; x == null ? ... : x.method(); or populating x
      from the parameters map.
    paths:
      exclude:
        - "**/src/test/**"
        - "**/test/**"
    patterns:
      - pattern-either:
          # (a) nullable URL component field 'urlAddress' dereferenced (dubbo-npe-c1-4)
          - patterns:
              - pattern-either:
                  - pattern: |
                      $T $V = urlAddress.$M(...);
                      return $R($V);
                  - pattern: |
                      return urlAddress.$M(...);
              - pattern-not-inside: |
                  if (<... urlAddress == null ...>) {
                    ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... null == urlAddress ...>) {
                    ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... urlAddress != null ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  if (<... null != urlAddress ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  urlAddress == null ? $A : $B
              - pattern-not-inside: |
                  null == urlAddress ? $A : $B
              - pattern-not-inside: |
                  urlAddress != null ? $A : $B
              - pattern-not-inside: |
                  null != urlAddress ? $A : $B
              - pattern-not-inside: |
                  if (...) {
                    ...
                  }
          # (b) nullable service-info lookup result dereferenced directly (dubbo-npe-c1-1)
          - pattern-either:
              - pattern: getServiceInfo(...).$M(...)
              - pattern: getValidServiceInfo(...).$M(...)
          # (c) nullable lookup stored in a local then dereferenced
          - patterns:
              - pattern-inside: |
                  $TYPE $SI = $LOOKUP(...);
                  ...
              - metavariable-regex:
                  metavariable: $LOOKUP
                  regex: "(getServiceInfo|getValidServiceInfo)$"
              - pattern: $SI.$M(...)
              - pattern-not-inside: |
                  if (<... $SI == null ...>) {
                    ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... null == $SI ...>) {
                    ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... $SI != null ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  if (<... null != $SI ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  $SI == null ? $A : $SI.$M(...)
              - pattern-not-inside: |
                  null == $SI ? $A : $SI.$M(...)
              - pattern-not-inside: |
                  $SI != null ? $SI.$M(...) : $A
              - pattern-not-inside: |
                  null != $SI ? $SI.$M(...) : $A
          # (d) URL username/password taken only from the inline
          # 'user:password@' userinfo segment, so they stay null when that
          # segment is missing or the body was truncated at '#' (dubbo-npe-c1-3)
          - patterns:
              - pattern-either:
                  - pattern: $BODY.indexOf('#')
                  - patterns:
                      - pattern: $STAR = $PWD_IDX + 1;
                      - pattern-inside: |
                          if ($PWD_IDX > 0) {
                            ...
                          }
              - pattern-inside: |
                  URL $M(...) {
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... $CRED == null ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... null == $CRED ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... $CRED != null ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... null != $CRED ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... isEmpty($CRED) ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... isNotEmpty($CRED) ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... $CRED.isEmpty() ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $CRED == null ? $A : $B
              - pattern-not-inside: |
                  null == $CRED ? $A : $B
              - pattern-not-inside: |
                  $CRED != null ? $A : $B
              - pattern-not-inside: |
                  null != $CRED ? $A : $B
          # (e) possibly-null invocation attachment (e.g. service path) used to
          # build the service key / cache key without validation (dubbo-npe-c1-5)
          - patterns:
              - pattern: String $PATH = (String) $INV.$GETTER($KEY);
              - metavariable-regex:
                  metavariable: $GETTER
                  regex: (?i).*attachment.*
              - pattern-inside: |
                  $RET $M(...) {
                    ...
                    $T $SK = serviceKey(..., $PATH, ...);
                    ...
                  }
              - pattern-not-inside: |
                  if (<... $PATH == null ...>) {
                    ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... null == $PATH ...>) {
                    ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... $PATH != null ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  if (<... null != $PATH ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  $PATH == null ? $A : $B
              - pattern-not-inside: |
                  null == $PATH ? $A : $B
              - pattern-not-inside: |
                  $PATH != null ? $A : $B
              - pattern-not-inside: |
                  null != $PATH ? $A : $B
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if ($PATH == null) {
                      ...
                    }
                    ...
                  }
